class CoordinatePoint {
    private final int x;
    private final int y;
    public CoordinatePoint(int x, int y) { this.x = x; this.y = y; }
    public boolean equalsPoint(CoordinatePoint other) {
        if (other == null) return false;
        return this.x == other.x && this.y == other.y;
    }
}
public class PointTest {
    public static void main(String[] args) {
        CoordinatePoint p1 = new CoordinatePoint(10, 20);
        CoordinatePoint p2 = new CoordinatePoint(10, 20);
        System.out.println(p1.equalsPoint(p2));
    }
}
